class AvgPartition:
    def __init__(self, lst, limit):
        self.lst = lst
        self.limit = limit

    def _partition_size(self, index):
        size = len(self.lst) // self.limit
        remainder = len(self.lst) % self.limit
        return size, remainder

    def _calc_end(self, index, size, remainder):
        return size + (1 if index + 1 <= remainder else 0)

    def get(self, index):
        size, remainder = self._partition_size(index)
        start = index * size + min(index, remainder)
        end = start + self._calc_end(index, size, remainder)
        return self.lst[start:end]
